import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

export type DeleteMessageArgs = Database['private']['Functions']['delete_message']['Args'];

export const useDeleteMessageFunc = async (data: DeleteMessageArgs) => {
  return withSupabase((supabase) => supabase.rpc('delete_message', data));
};

export type GetMessagesResponse = Awaited<ReturnType<typeof useDeleteMessageFunc>>;
