<template>
  <Dialog v-model:open="model">
    <DialogContent class="rounded-lg max-w-xs sm:max-w-sm gap-6">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">Are you sure you want to delete this message?</DialogTitle>
      </DialogHeader>

      <DialogFooter>
        <div class="flex flex-wrap justify-end gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4">Cancel</Button>
          </DialogClose>
          <Button
            variant="destructive"
            :loading="isDeletingMessage"
            :disabled="isDeletingMessage"
            @click="confirmDelete"
            >Confirm</Button
          >
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { useDeleteMessage } from '~/mutations/chats/deleteMessage';

interface Props {
  messageId: number | null;
}

const props = defineProps<Props>();

const model = defineModel<boolean>('open', { default: false });

const { deleteMessage, isDeletingMessage } = useDeleteMessage();

async function confirmDelete() {
  if (props.messageId)
    await deleteMessage({ input: { message_id: props.messageId } }).then(() => {
      model.value = false;
    });
  else showToastError('Failed to delete message');
}
</script>
