import type { QueryData, PostgrestSingleResponse } from '@supabase/supabase-js';
import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

type GetChatParticipantsArgs = Database['private']['CompositeTypes']['get_chat_participants_with_details_input'];

export const useGetChatParticipants = async (data: GetChatParticipantsArgs) => {
  return withSupabase((supabase) => supabase.rpc('get_chat_participants_with_details', { input: data }));
};

export type ChatParticipant = Database['private']['Functions']['get_chat_participants_with_details']['Returns'][0];
export type GetChatParticipantsResponse = PostgrestSingleResponse<QueryData<ReturnType<typeof useGetChatParticipants>>>;
