<template>
  <ChatsMainHeader :data="headerData" :loading="isChatInfoLoading" :muted="isChatMuted" />
  <Separator />
  <AppLoader
    v-if="isChatInfoLoading || isChatParticipantsLoading"
    variant="table"
    subject="chat information"
    class="h-full w-full"
  />
  <AppError
    v-else-if="messagesError"
    :message="messagesError.message || 'An error occurred while loading messages.'"
    variant="table"
    class="h-full w-full"
    action-text=""
    title="Failed to load messages"
  />
  <ChatsMain2
    v-else-if="messages && chatInfo"
    ref="chatMain"
    :loading="isChatInfoLoading || isChatParticipantsLoading || isMessagesLoading"
    :chat-id="id"
    :limit="limit"
    :data="messages"
    :last-message-id-in-view="openAt"
    :last-read-message-id="chatInfo?.last_read_message_id"
    :last-message-in-chat="{ id: chatInfo?.last_message_id, userId: chatInfo?.last_message_sender_id }"
    :last-users-read-message-id="lastUsersReadMessageId"
    :chat-info-data="chatInfoData"
    :editing-message-id="messageToEdit?.id"
  >
    <template #inputs>
      <div v-if="chatInfoData?.data?.archived_at" class="flex justify-center mb-2">
        <Alert class="p-2 w-11/12">
          <div class="flex gap-2 items-center">
            <InfoIcon />
            <div class="flex flex-col gap-1">
              <AlertTitle :class="cn({ 'mb-0': !isAdminOrManager })">Chat was archived.</AlertTitle>
              <AlertDescription v-if="isAdminOrManager"
                >{{ chatInfoData?.data.type === 'DM' ? 'This user was deactivated.' : '' }} You cannot send messages
                here anymore.</AlertDescription
              >
            </div>
          </div>
        </Alert>
      </div>
      <ChatsInputs
        v-else-if="!Boolean(chatInfoData?.data?.type === 'CHANNEL' && chatInfoData?.data?.role === 'LISTENER')"
        v-model:input-text="inputMessage"
        v-model:files="files"
        v-model:group="groupId"
        :loading="isSendingMessage || isSendProcessing"
        :chat-id="id"
        :message-to-edit="messageToEdit"
        :message-to-reply="messageToReply"
        @send="handleSend"
        @cancel-edit="onCancelEdit"
        @confirm-edit="onConfirmEdit"
        @cancel-reply="onCancelReply"
      />
    </template>
  </ChatsMain2>
  <ChatsMessageContextMenu
    ref="contextMenu"
    v-model:message="messageDataForContextMenu"
    :can-copy-text="Boolean(messageDataForContextMenu && messageDataForContextMenu.body)"
    :can-reply="
      Boolean(messageDataForContextMenu) && !chatInfoData?.data?.archived_at && chatInfoData?.data?.role !== 'LISTENER'
    "
    :can-edit="isUserMessage && !chatInfoData?.data?.archived_at"
    :can-delete="isUserMessage && !chatInfoData?.data?.archived_at"
    @delete-trigger="setMessageToDelete"
    @edit-trigger="setMessageToEdit"
    @reply-trigger="setMessageToReply"
  />
  <ChatsMessageDeleteDialog
    v-if="messageToDelete?.id"
    v-model:open="deleteModal"
    :message-id="messageToDelete.id"
    @update:open="onDeleteModalClose"
  />
</template>

<script setup lang="ts">
import { InfoIcon } from 'lucide-vue-next';
import { useSendMessage } from '~/mutations/chats/sendMessage';
import {
  useChatMessagesAt,
  useChatMessages,
  type ChatMessage,
  type Timeline,
} from '~/composables/supabase/useChatMessages';
import type { GetChatInfoResponse, ChatInfo } from '~/composables/supabase/useChatInfo';
import {
  useGetChatParticipants,
  type ChatParticipant,
  type GetChatParticipantsResponse,
} from '~/composables/supabase/useGetChatParticipants';
import type { SendMessageArgs } from '~/composables/supabase/useSendMessage';
import { useFileToChatProcessing } from '~/composables/supabase/fileToChatProcessing';
import { cn } from '@/lib/utils';

definePageMeta({
  backLabel: 'chat',
});

interface Props {
  chatInfoData: GetChatInfoResponse | undefined;
  isChatInfoLoading: boolean;
}

const props = defineProps<Props>();

const route = useRoute('chats-id');

const id = computed(() => route.params.id);
const isChatMuted = computed(() => Boolean(props.chatInfoData?.data?.muted_until));

const { userId, isAdminOrManager } = useUserRole();

const limit = 50;

const messageToEdit = ref<ChatMessage | null>(null);
const messageToReply = ref<ChatMessage | null>(null);
const messageToDelete = ref<ChatMessage | null>(null);
const deleteModal = ref<boolean>(false);

const openAt = computed(() => {
  if (chatInfo.value?.last_message_sender_id === userId.value) return chatInfo.value?.last_message_id || null;
  if (!chatInfo.value?.last_read_message_id) return null;
  if (chatInfo.value?.last_message_id && chatInfo.value?.last_read_message_id < chatInfo.value?.last_message_id)
    return chatInfo.value?.last_read_message_id;
  return null;
});

const { data: chatParticipantsData, isLoading: isChatParticipantsLoading } = useQuery({
  key: () => ['chatParticipants.id', id.value],
  query: () => useGetChatParticipants({ chat_id: id.value, page: null, size: null }),
  enabled: () => !!id.value,
});

const chatInfo = computed(() => props.chatInfoData?.data ?? null);
const profiles = computed(() => chatParticipantsData.value?.data ?? []);
const lastUsersReadMessageId = computed(() => {
  if (!profiles.value.length) return null;
  return Math.max(
    ...profiles.value
      .filter((profile) => profile.id !== userId.value)
      .map((profile) => profile.last_read_message_id ?? 0)
  );
});
const headerData = computed(() => ({
  title: chatInfo.value?.title ?? '',
  avatarUrl: chatInfo.value?.avatar_url ?? '',
  role: chatInfo.value?.type === 'DM' ? props.chatInfoData?.data?.dm_with_user_role || null : null,
  type: props.chatInfoData?.data?.type ?? null,
  id:
    chatInfo.value?.type === 'DM'
      ? (props.chatInfoData?.data?.dm_with_user_id ?? '')
      : (props.chatInfoData?.data?.id ?? ''),
}));

const {
  data: messages,
  isLoading: isMessagesLoading,
  error: messagesError,
} = useQuery({
  key: () => ['messages.id', id.value],
  query: async (): Promise<Timeline> => {
    let res = undefined;
    if (openAt.value) {
      res = await useChatMessagesAt({
        chat_id: id.value,
        at_message_id: openAt.value,
        message_limit: limit,
      });
    } else {
      res = await useChatMessages({
        chat_id: id.value,
        before_message_id: null,
        after_message_id: null,
        message_limit: limit,
      });
    }

    if (res?.error) {
      captureExceptionToSentry(new Error('Failed to get chat messages: ' + res.error.message));
      throw new Error('Failed to get chat messages');
    }

    const items = res?.data ?? [];
    return {
      items,
      error: res?.error,
      oldestId: items[0]?.id ?? null,
      newestId: items.at(-1)?.id ?? null,
      hasOlder: (res?.data?.length ?? 0) === limit,
      hasNewer:
        items.at(-1)?.id != null &&
        chatInfo.value?.last_message_id != null &&
        Number(items.at(-1)?.id) < Number(chatInfo.value?.last_message_id),
    };
  },
  enabled: () => !!id.value && !!props.chatInfoData,
  staleTime: 0,
});

const inputMessage = ref<string>('');
const files = ref<UploadItem[]>([]);
const groupId = ref<string | null>(null);
const isSendProcessing = ref<boolean>(false);

const { sendMessage, isSendingMessage } = useSendMessage();
const { handleFiles } = useFileToChatProcessing();

async function handleSend(data: SendMessageArgs) {
  if (files.value.length) {
    try {
      await handleFiles({
        chatId: id.value,
        files: files.value,
        userId: userId.value,
        groupId: data.attachment_group_id!,
      });
    } catch (err) {
      console.error(err);
      showToastError('Please try to reattach files', 'Failed to send message');
      captureExceptionToSentry(new Error('Failed to move files from draft folder for message: ' + err));
      return;
    }
  }
  isSendProcessing.value = true;
  await sendMessage({ data })
    .then(() => {
      inputMessage.value = '';
      files.value = [];
      groupId.value = null;
      messageToReply.value = null;
    })
    .catch((err) => {
      console.error(err);
      showToastError('Please try to resend the message', 'Failed to send message');
      captureExceptionToSentry(new Error('Failed to send message: ' + err));
    })
    .finally(() => {
      isSendProcessing.value = false;
      document.getElementById('inputField')?.focus();
    });
}

const chatMain = ref<{
  onSendMessage: (message: ChatMessage) => Promise<void>;
} | null>(null);

const queryCache = useQueryCache();

function patchChatParticipant(participant: ChatParticipant) {
  queryCache.setQueryData<GetChatParticipantsResponse | undefined>(['chatParticipants.id', id.value], (prev) => {
    if (!prev) return prev;

    if (!prev.data) return prev;

    const updatedParticipants = prev.data.map((user) => {
      if (user.id === participant.id) {
        return participant;
      }
      return user;
    });

    return {
      ...prev,
      data: updatedParticipants,
    };
  });
}

function updateChatCounters(message: ChatMessage) {
  queryCache.setQueryData<GetChatInfoResponse | undefined>(['chatInfo.id', id.value], (prev) => {
    if (!prev) return prev;

    if (!prev.data) return prev;

    return {
      ...prev,
      data: {
        ...prev.data,
        last_message_at: message.created_at,
        last_message_id: message.id,
        last_message_preview: message.body,
        last_message_sender_id: message.sender_id,
      },
    };
  });
}

function updateMessageOnEdit(message: ChatMessage) {
  queryCache.setQueryData<Timeline | undefined>(['messages.id', id.value], (prev) => {
    if (!prev) return prev;

    if (!prev.items) return prev;

    const updatedItems = prev.items.map((item) => {
      if (item.id === message.id) {
        return message;
      }
      if (item.reply_to_message_id === message.id) {
        return {
          ...item,
          reply_to_message_sender_display_name: message.sender_display_name,
          reply_to_message_attachments: message.attachments,
          reply_to_message_attachment_group_id: message.attachment_group_id,
          reply_to_message_preview: message.body,
        };
      }
      return item;
    });

    return {
      ...prev,
      items: updatedItems,
    };
  });
}

function onDeleteMessage(message: ChatMessage) {
  queryCache.setQueryData<Timeline | undefined>(['messages.id', id.value], (prev) => {
    if (!prev) return prev;

    if (!prev.items) return prev;

    const updatedItems = prev.items
      .filter((item) => item.id !== message.id)
      .map((item) => {
        if (item.reply_to_message_id === message.id) {
          return {
            ...item,
            reply_to_message_attachment_group_id: null,
            reply_to_message_sender_display_name: null,
            reply_to_message_attachments: [],
            reply_to_message_preview: null,
            reply_to_message_deleted: true,
          };
        }
        return item;
      });

    return {
      ...prev,
      items: updatedItems,
    };
  });
}

function onEditChatDetails(data: ChatInfo) {
  queryCache.setQueryData<GetChatInfoResponse | undefined>(['chatInfo.id', id.value], (prev) => {
    if (!prev) return prev;

    if (!prev.data) return prev;

    return {
      ...prev,
      data: {
        ...prev.data,
        ...data,
      },
    };
  });
}

const unsub = ref<any>(null);

onMounted(async () => {
  //TODO: add chat participants change event if it's needed()
  const { $realtimeManager } = useNuxtApp();
  unsub.value = $realtimeManager.register((supabase) => {
    return supabase
      .channel(`chat:${id.value}`, {
        config: { private: true, broadcast: { ack: true } },
      })
      .on('broadcast', { event: 'new_message' }, async (event: { payload: { record: ChatMessage } }) => {
        updateChatCounters(event.payload.record);
        if (!messages.value?.hasNewer) await chatMain.value?.onSendMessage(event.payload.record);
      })
      .on('broadcast', { event: 'edit_message' }, async (event: { payload: { record: ChatMessage } }) => {
        updateMessageOnEdit(event.payload.record);
      })
      .on('broadcast', { event: 'delete_message' }, async (event: { payload: { record: ChatMessage } }) => {
        onDeleteMessage(event.payload.record);
      })
      .on('broadcast', { event: 'edit_chat_details' }, async (event: { payload: { record: ChatInfo } }) => {
        onEditChatDetails(event.payload.record);
      })
      .on('broadcast', { event: 'edit_participant' }, async (event: { payload: { record: ChatParticipant } }) => {
        patchChatParticipant(event.payload.record);
      })
      .on('system', { event: '*' }, async (event) => {
        if (event?.message?.includes('Token has expired')) {
          console.warn('Token has expired, refreshing...');
          await $realtimeManager.refresh();
        }
      })
      .subscribe();
  });
});

onUnmounted(() => {
  if (unsub.value) unsub.value();
  inputMessage.value = '';
  files.value = [];
  groupId.value = null;
  messageToReply.value = null;
  messageToEdit.value = null;
});

function setMessageToEdit(message: ChatMessage | null) {
  if (messageToReply.value) onCancelReply();
  messageToEdit.value = message;
  document.getElementById('inputField')?.focus();
  files.value = [];
  groupId.value = null;
}

function onCancelEdit() {
  setMessageToEdit(null);
}

function onConfirmEdit() {
  setMessageToEdit(null);
}

function setMessageToReply(message: ChatMessage | null) {
  if (messageToEdit.value) {
    inputMessage.value = '';
    onCancelEdit();
  }
  messageToReply.value = message;
  document.getElementById('inputField')?.focus();
}

function onCancelReply() {
  setMessageToReply(null);
}

function setMessageToDelete(message: ChatMessage | null) {
  messageToDelete.value = message;
  deleteModal.value = true;
}

function onDeleteModalClose(isOpen: boolean) {
  if (!isOpen) {
    messageToDelete.value = null;
  }
}

const contextMenu = ref<{
  openAt: (point: { x: number; y: number }) => Promise<void>;
  closeMenu: () => void;
  isClosedByOutsidePointerDown: () => boolean;
} | null>(null);

const messageDataForContextMenu = ref<ChatMessage | null>(null);

const isUserMessage = computed(
  () =>
    messageDataForContextMenu.value?.sender_id === userId.value ||
    (props.chatInfoData?.data?.type === 'CHANNEL' &&
      (props.chatInfoData?.data?.role === 'ADMIN' || props.chatInfoData?.data?.role === 'OWNER'))
);

async function messageContextMenuTrigger(messageItem: ChatMessage | null, pointer: { x: number; y: number } | null) {
  if (pointer && contextMenu.value) {
    linkMenuCloseSignal.value++;
    // Toggle close: if the pointerdown that fired this click already closed the menu via Radix
    // outside-detect AND the target is the same message that was open, treat the gesture as a
    // close, not a re-open. (Same-id check vs `messageDataForContextMenu` instead of `open` is
    // necessary because Radix has already flipped `open` to false by the time `click` runs.)
    if (contextMenu.value.isClosedByOutsidePointerDown() && messageDataForContextMenu.value?.id === messageItem?.id) {
      return;
    }
    messageDataForContextMenu.value = messageItem;
    await contextMenu.value.openAt(pointer);
  }
}

provide('messageContextMenuTrigger', messageContextMenuTrigger);
</script>
