import { type DeleteMessageArgs, useDeleteMessageFunc } from '~/composables/supabase/useDeleteMessage';

export const useDeleteMessage = defineMutation(() => {
  const { mutateAsync: deleteMessage, asyncStatus } = useMutation({
    mutation: (data: DeleteMessageArgs) => useDeleteMessageFunc(data),
    onSuccess: (response) => {
      if (response.error) {
        console.error('Failed to delete message:', response.error);
        throw new Error('Failed to delete message');
      }
    },
    onError: (err) => {
      showToastError(err);
    },
  });

  return {
    deleteMessage,
    isDeletingMessage: computed(() => asyncStatus.value === 'loading'),
  };
});
