<template>
  <ContextMenu v-if="hasMenu" v-model:open="open" :modal="false" @update:open="open = $event">
    <ContextMenuTrigger as-child>
      <div ref="triggerEl" class="contents" @pointerdown="() => {}" @click.capture="() => {}">
        <slot />
      </div>
    </ContextMenuTrigger>

    <ContextMenuContent
      @pointer-down-outside="onPointerDownOutside"
      @focus-outside="open = false"
      @interact-outside="open = false"
    >
      <ContextMenuItem v-if="canReply" @select="$emit('reply-trigger', messageData)"
        ><ReplyIcon class="w-5 h-5 mr-2" /> Reply</ContextMenuItem
      >
      <ContextMenuItem v-if="canCopyText" @select="onCopyTextTrigger"
        ><CopyIcon class="w-5 h-5 mr-2" /> Copy</ContextMenuItem
      >
      <ContextMenuItem v-if="canEdit" @select="$emit('edit-trigger', messageData)"
        ><EditIcon class="w-5 h-5 mr-2" /> Edit</ContextMenuItem
      >
      <ContextMenuItem
        v-if="canDelete"
        class="text-destructive focus:text-destructive"
        @select="$emit('delete-trigger', messageData)"
      >
        <Trash2Icon class="w-5 h-5 mr-2" /> Delete
      </ContextMenuItem>
    </ContextMenuContent>
  </ContextMenu>

  <slot v-else />
</template>

<script setup lang="ts">
import { Trash2Icon, EditIcon, ReplyIcon, CopyIcon } from 'lucide-vue-next';
import { ContextMenu, ContextMenuTrigger, ContextMenuContent, ContextMenuItem } from '~/components/ui/context-menu';
import type { ChatMessage } from '~/composables/supabase/useChatMessages';

const props = withDefaults(
  defineProps<{
    canCopyText?: boolean;
    canReply?: boolean;
    canEdit?: boolean;
    canDelete?: boolean;
  }>(),
  {
    canCopyText: false,
    canReply: false,
    canEdit: false,
    canDelete: false,
  }
);

interface Emits {
  (e: 'delete-trigger', messageData: ChatMessage | null): void;

  (e: 'edit-trigger', messageData: ChatMessage | null): void;

  (e: 'reply-trigger', messageData: ChatMessage | null): void;
}

defineEmits<Emits>();

const hasMenu = computed(() => props.canReply || props.canCopyText || props.canEdit || props.canDelete);
const open = defineModel<boolean>('open', { default: false });
const messageData = defineModel<ChatMessage | null>('message', { default: null });

// True for the duration of the click that follows a Radix outside-pointerdown close.
// The pointerdown that closes the menu is the same gesture that fires the `click` on
// the message; without this signal, the parent trigger can't tell "I tapped the same
// open message to close it" (toggle close — should not reopen) from "I tapped this
// message after closing the menu by tapping somewhere else" (should reopen on 1 tap).
const closedByOutsidePointerDown = ref(false);

function onPointerDownOutside() {
  open.value = false;
  closedByOutsidePointerDown.value = true;
  // Reset on the next macrotask — fires after the click handler for the same tap has run.
  setTimeout(() => {
    closedByOutsidePointerDown.value = false;
  }, 0);
}

const triggerEl = ref<HTMLElement | null>(null);

function pressEsc() {
  window.dispatchEvent(
    new KeyboardEvent('keydown', {
      key: 'Escape',
      code: 'Escape',
      bubbles: true,
      cancelable: true,
    })
  );
}

async function openAt(point: { x: number; y: number }) {
  if (open.value) {
    pressEsc();
    messageData.value = null;
    open.value = false;
    return;
  } else {
    await nextTick(() => {
      triggerEl.value?.dispatchEvent(
        new MouseEvent('contextmenu', {
          bubbles: true,
          cancelable: true,
          clientX: point.x,
          clientY: point.y,
        })
      );
    });
  }
}

defineExpose({
  openAt,
  closeMenu: pressEsc,
  isClosedByOutsidePointerDown: () => closedByOutsidePointerDown.value,
});

function onCopyTextTrigger() {
  try {
    if (!messageData.value?.body) {
      showToastError('No text to copy');
      return;
    } else {
      try {
        navigator.clipboard.writeText(messageData.value.body);
      } catch (error) {
        console.error('Failed to copy text:', error);
        showToastError('Failed to copy text');
        captureExceptionToSentry(new Error('Failed to copy message text: ' + error));
      }
    }
  } catch (error) {
    console.error('Failed to copy text:', error);
    showToastError('Failed to copy text');
    captureExceptionToSentry(new Error('Failed to copy message text: ' + error));
  }
}
</script>
